head.script:
scwin.openPop = function(id, pos) {
	var opts = {
		"id": id,
		"type": "litewindow",
		"width": "300px",
		"height": "300px",
		"top": pos,
		"left": pos,
		"popupName": "focusTest",
		"modal": false,
		"useIFrame": true,
		"title": "focusTest"
	};
	$p.openPopup("/sample/common_link/p_popup_ngmf.open_SKT-373_(WSQ-1002)_sub.xml", opts);
};
scwin.trigger1_onclick = function(e) {
	scwin.openPop("popup1", 50);
};
scwin.trigger2_onclick = function(e) {
	scwin.openPop("popup2", 150);
};
scwin.trigger3_onclick = function(e) {
	scwin.openPop("popup3", 250);
};
scwin.checkEl = function(id) {
	return !!(document.getElementById($p.id + id) || document.getElementById(id));
};
